// Package testcorpus defines authored, deterministic parity inputs. It uses no
// toolchain Unicode predicates or case mappings and no external evaluation data.
package testcorpus

import (
	"strings"
	"unicode/utf8"
)

// Version changes whenever the generated byte stream changes.
const Version = 1

// Seed fixes the generated corpus.
const Seed uint64 = 931

// Count is the number of offline parity cases.
const Count = 250000

var categories = [...]string{"code", "prose", "scripts", "marks", "markers", "seams", "digits", "scalars", "whitespace", "long"}

var atoms = [...][]string{
	{"func Count(s string) int { return len(s) }\n", "{\"key\": [1, true, null]}", "#!/bin/sh\nprintf '%s\\n' \"$HOME\"", "!= == += := :: -> => / * ** && ||", "\t// TODO: explain\n", "Foo_Bar99", "\\\"{}[]<>"},
	{"# Heading\n\n", "A sentence, with punctuation. ", "**Bold** and `code`", "we're can't I'll they've", "Hello world!\n", "UPPER Title mIxEd", "[link](https://example.invalid/)"},
	{"Καλημέρα κόσμε", "Привет мир", "مرحبا بالعالم", "ܐܒܓ ܕܗ", "שלום עולם", "नमस्ते दुनिया", "ภาษาไทย", "中文 日本語 한국어", "İ I ı i ẞ ß", "ϴ Θ Σ σ ς"},
	{"\u0301", "\u0315\u0300", "\u0345", "a\u0301", "\u0711", "ܐ\u0730", "\u05b0", "\u0e4d\u0e32", "\u1100\u1161\u11a8", "👩\u200d💻", "🏳️\u200d🌈", "\ufe0f\u20e3"},
	{"\ufdd0", "\ufdd1", "\ufdd2", "\ufdd3", "\ufdd4", "\ue000", "\uf8ff", "\U000f0000", "x\ufdd0y", "\x00\x01\x08\x0b\x7f\u0085", "\ufeff"},
	{"a", "A", "I", "'s", "'t", "'re", "'ve", "'ll", "'d", "'m", "’s", "-", ".", ",", " ", "\n", "\t", "\u0300", "ܐ", "\u0711", "😀"},
	{"0", "1234567890", "١٢٣", "१२३", "１２３", "1.23e-9", "a1b2", "_123_", "Ⅳ", "²", "+-*/=<>"},
	nil,
	{" ", "\n", "\t", "\r\n", "\u00a0", "\u1680", "\u2000", "\u200b", "\u2028", "\u2029", "\u202f", "\u205f", "\u3000", "\x00"},
	{"a ", "A ", "word ", "\n", "\u0301", "\u0315\u0300", "中文", "😀", "x123 ", "abc\tdef\n"},
}

var fixed = [...]string{"", "\n", "\n\n", "\x01\x7f\ue000", "Hello", "hello", "HELLO", "can't", "a b", "a\nb", "\u0301a", "ܐ\u0730", "\ufdd0\ufdd1\ufdd2\ufdd3\ufdd4", "a\n\n\n", "İstanbul", "ẞ", "a's", "a’b", "\u0711ܐ", "a\u0301\u0315\u0300"}

type random struct{ state uint64 }

func (r *random) next() uint64 {
	r.state += 0x9e3779b97f4a7c15
	z := r.state
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

// Category returns the stable category name for index.
func Category(index int) string {
	if index < len(fixed) {
		return "fixed"
	}
	return categories[index%len(categories)]
}

// Case returns the valid UTF-8 input at index, for 0 <= index < Count.
func Case(index int) string {
	if index < len(fixed) {
		return fixed[index]
	}
	r := random{Seed + uint64(index)*0xd1342543de82ef95}
	category := index % len(categories)
	n := 1 + int(r.next()%24)
	var out strings.Builder
	if category == 9 {
		// Thirty very large cases, bounded at 100 KiB each.
		if index < 320 {
			n = 100 * 1024
		} else {
			n = 1 + int(r.next()%128)
		}
		atom := atoms[category][r.next()%uint64(len(atoms[category]))]
		for out.Len()+len(atom) <= n {
			out.WriteString(atom)
		}
		return out.String()
	}
	for range n {
		if category == 7 {
			cp := rune(r.next() % 0x110000)
			if cp >= 0xd800 && cp <= 0xdfff {
				cp = utf8.RuneError
			}
			out.WriteRune(cp)
		} else {
			pool := atoms[category]
			out.WriteString(pool[r.next()%uint64(len(pool))])
		}
	}
	return out.String()
}
